/* Official-documentation layer: adds a "📚 Official docs" block to each question card from window.DOCS[<guideKey>]
 * (generated by tools/build_docs.mjs into docs/<guideKey>.js). Entries: [label, url] or [label, url, 1] for a generic "start here" link.
 * Offline-safe: plain script tags; links open in a new tab. Survives the guides' re-renders via MutationObserver. */
(function () {
  'use strict';
  var file = location.pathname.split('/').pop() || '';
  var key = file.replace(/\.html$/, '').replace(/_interview_guide$|_guide$/, '');
  var set = (window.DOCS || {})[key];
  if (!set) return;
  var st = document.createElement('style');
  st.textContent = '.docs-block{margin:12px 0 0;padding:10px 14px;border:1px solid rgba(24,95,165,.3);border-left:4px solid #185FA5;border-radius:10px;background:rgba(24,95,165,.06);font-size:13px;line-height:1.55}' +
    'body.dark .docs-block{background:rgba(120,170,230,.08);border-color:rgba(120,170,230,.35);border-left-color:#7ab0ec}' +
    '.docs-title{font-weight:600;font-size:12.5px;margin-bottom:4px}.docs-block ul{margin:0 0 0 18px;padding:0}.docs-block a{color:#185FA5;word-break:break-word}' +
    'body.dark .docs-block a{color:#8dbdf0}.docs-note{margin-top:6px;font-size:11.5px;opacity:.75}';
  document.head.appendChild(st);
  function el(t, c, x) { var e = document.createElement(t); if (c) e.className = c; if (x) e.textContent = x; return e; }
  function build(n, links) {
    var generic = links.length === 1 && links[0][2] === 1;
    var b = el('div', 'docs-block'); b.setAttribute('data-docs', n);
    b.appendChild(el('div', 'docs-title', generic ? '📚 Start here (official docs)' : '📚 Official docs'));
    var ul = el('ul');
    links.forEach(function (l) {
      var li = el('li'), a = el('a', '', l[0]);
      a.href = l[1]; a.target = '_blank'; a.rel = 'noopener noreferrer'; li.appendChild(a); ul.appendChild(li);
    });
    b.appendChild(ul);
    return b;
  }
  function inject() {
    var cards = document.querySelectorAll('.q-card[id^="card-"]');
    for (var i = 0; i < cards.length; i++) {
      var c = cards[i], n = c.id.slice(5), links = set[n];
      if (!links) continue;
      var body = c.querySelector('.q-body');
      if (body && !body.querySelector('.docs-block')) body.appendChild(build(n, links));
    }
  }
  var pending = false;
  new MutationObserver(function () {
    if (pending) return; pending = true;
    requestAnimationFrame(function () { pending = false; inject(); });
  }).observe(document.body, { childList: true, subtree: true });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', inject); else inject();
})();
